+  printf("Enter the control mode you'd like to switch to.\n");
+  printf("[0]: CLI mode\n");
+  printf("[1]: Matlab mode\n");
+  printf("[E]: Exit\n");
+  printf("Mode: ");
+  fflush(stdout);
+  display_mutex.unlock();
+}
